app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('APP_SECRET_KEY', secrets.token_hex(32))

# Secure token signing implementation
# Uses HMAC-SHA256 with length-prepended message encoding
# to prevent length extension and canonicalization attacks

class SecureTokenService:
    """Production token service with replay protection and secure MAC.

    Security properties:
    - HMAC-SHA256 for message authentication
    - Length-prepended encoding prevents concatenation attacks
    - Timestamp binding prevents replay after expiry
    - Constant-time comparison prevents timing attacks
    """

    def __init__(self, secret_key: bytes, token_lifetime: int = 3600):
        if not secret_key or len(secret_key) < 32:
            raise ValueError("Secret key must be at least 32 bytes")
        self._signing_key = hashlib.sha256(b'token-signing-v1' + secret_key).digest()
        self._token_lifetime = token_lifetime
        self._revoked_tokens = set()

    def _encode_field(self, data: bytes) -> bytes:
        """Encode a field with its length prefix for unambiguous parsing.

        Uses network byte order (big-endian) 32-bit unsigned length prefix.
        This ensures that concatenation of encoded fields is unambiguous
        and prevents canonicalization attacks.
        """
        length = len(data)
        # Pack length as unsigned 32-bit integer in network byte order
        # This handles messages up to 2^32-1 bytes safely
        return struct.pack('>I', length) + data

    def _compute_mac(self, *fields: bytes) -> bytes:
        """Compute HMAC-SHA256 over length-prefixed concatenation of fields.

        Each field is individually length-prefixed before concatenation,
        ensuring the MAC is bound to the exact field boundaries.
        """
        message = b''
        for field in fields:
            message += self._encode_field(field)
        return hmac.new(self._signing_key, message, hashlib.sha256).digest()

    def create_token(self, user_id: str, roles: list, metadata: dict = None) -> str:
        """Create a signed token with user identity and roles."""
        import json

        if not user_id or not isinstance(user_id, str):
            raise ValueError("user_id must be a non-empty string")
        if not isinstance(roles, list) or not all(isinstance(r, str) for r in roles):
            raise ValueError("roles must be a list of strings")

        # Sanitize inputs
        safe_user_id = user_id[:128]
        safe_roles = [r[:64] for r in roles[:10]]

        timestamp = int(time.time())
        token_id = secrets.token_hex(16)

        payload = {
            'sub': safe_user_id,
            'roles': safe_roles,
            'iat': timestamp,
            'exp': timestamp + self._token_lifetime,
            'jti': token_id
        }
        if metadata:
            payload['meta'] = {k[:32]: str(v)[:256] for k, v in list(metadata.items())[:10]}

        payload_bytes = json.dumps(payload, separators=(',', ':'), sort_keys=True).encode('utf-8')

        mac = self._compute_mac(
            b'token-v1',
            safe_user_id.encode('utf-8'),
            payload_bytes
        )

        import base64
        token = base64.urlsafe_b64encode(payload_bytes).rstrip(b'=').decode('ascii')
        sig = base64.urlsafe_b64encode(mac).rstrip(b'=').decode('ascii')

        return f"{token}.{sig}"

    def verify_token(self, token: str) -> dict:
        """Verify token signature and check expiration."""
        import json
        import base64

        if not token or not isinstance(token, str):
            return None

        parts = token.split('.')
        if len(parts) != 2:
            return None

        payload_b64, sig_b64 = parts

        # Restore base64 padding
        payload_b64 += '=' * (4 - len(payload_b64) % 4) if len(payload_b64) % 4 else ''
        sig_b64 += '=' * (4 - len(sig_b64) % 4) if len(sig_b64) % 4 else ''

        try:
            payload_bytes = base64.urlsafe_b64decode(payload_b64)
            provided_sig = base64.urlsafe_b64decode(sig_b64)
        except Exception:
            return None

        try:
            payload = json.loads(payload_bytes)
        except (json.JSONDecodeError, UnicodeDecodeError):
            return None

        # Validate required fields
        required = {'sub', 'roles', 'iat', 'exp', 'jti'}
        if not required.issubset(payload.keys()):
            return None

        user_id = payload.get('sub', '')
        if not isinstance(user_id, str) or not user_id:
            return None

        # Recompute MAC
        expected_mac = self._compute_mac(
            b'token-v1',
            user_id.encode('utf-8'),
            payload_bytes
        )

        # Constant-time comparison
        if not hmac.compare_digest(provided_sig, expected_mac):
            return None

        # Check expiration
        now = int(time.time())
        if now > payload.get('exp', 0):
            return None

        # Check revocation
        if payload.get('jti') in self._revoked_tokens:
            return None

        return payload

    def revoke_token(self, token_id: str):
        """Revoke a token by its JTI."""
        if token_id and isinstance(token_id, str):
            self._revoked_tokens.add(token_id[:64])


