def require_auth(f):
    """Authentication decorator that validates bearer tokens."""
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            abort(401)

        token = auth_header[7:]
        if len(token) > 4096:
            abort(401)

        payload = token_service.verify_token(token)
        if payload is None:
            abort(401)

        request.token_payload = payload
        return f(*args, **kwargs)
    return decorated


def require_role(role: str):
    """Authorization decorator that checks for specific role."""
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            payload = getattr(request, 'token_payload', None)
            if not payload:
                abort(401)
            if role not in payload.get('roles', []):
                abort(403)
            return f(*args, **kwargs)
        return decorated
    return decorator


